input.command:
mkdir -p /tmp/etltest && cd /tmp/etltest && cat > edge.sql <<'EOF'
DROP SCHEMA IF EXISTS etl_test CASCADE;
CREATE SCHEMA etl_test;
SET search_path TO etl_test;
\i /work/source/schema.sql
\i /work/dashboard_schema.sql
-- small seed inside the test schema
SELECT 1;
EOF
python3 /work/source/seed.py --print-only --rows 1000 > seed1k.sql
cat > edge_data.sql <<'EOF'
-- multi-category COMPLETED order: lines 900010 (product 1) and 900020 (product 2)
-- controlling line = 900010 (lowest id)
INSERT INTO orders VALUES (1000001, 1, '2026-01-15 10:00+00', 'COMPLETED', 0);
INSERT INTO order_items VALUES (900020, 1000001, 2, 3, 10.00);
INSERT INTO order_items VALUES (900010, 1000001, 1, 2, 99.99);
-- COMPLETED order with no lines
INSERT INTO orders VALUES (1000002, 2, '2026-01-20 10:00+00', 'COMPLETED', 0);
-- CANCELLED order with no lines (must not count)
INSERT INTO orders VALUES (1000003, 3, '2026-01-21 10:00+00', 'CANCELLED', 0);
EOF
cat > run.sql <<'EOF'
\set ON_ERROR_STOP 1
\i /tmp/etltest/edge.sql
\i /tmp/etltest/seed1k.sql
\i /tmp/etltest/edge_data.sql
SET search_path TO etl_test;
\i /work/etl.sql
\i /work/etl.sql
SELECT 'cat' t, * FROM dash_revenue_by_category WHERE month='2026-01' AND category IN ('(no items)', (SELECT category FROM products WHERE product_id=1)) ORDER BY 2;
SELECT 'run' t, source_order_count, loaded_order_count, mismatch FROM etl_run_log ORDER BY run_id;
SELECT 'sumcat' t, SUM(order_count) FROM dash_revenue_by_category;
SELECT 'completed' t, COUNT(*) FROM orders WHERE status='COMPLETED';
SELECT 'rows' t, (SELECT COUNT(*) FROM dash_revenue_by_category) c, (SELECT COUNT(*) FROM dash_revenue_by_country) k;
EOF
psql -v ON_ERROR_STOP=1 -q -f run.sql 2>&1 | grep -v NOTICE

